/* GreenSolutions 4.0.1 - ajuda das telas de questionarios. */
SET NAMES utf8mb4;

INSERT INTO ajuda_transacoes
    (transacao,titulo_pt,titulo_en,titulo_es,texto_pt,texto_en,texto_es,ativo)
VALUES
('questionario_legal','Ajuda - Questionario Legal','Help - Legal Questionnaire','Ayuda - Cuestionario Legal',
 '<p>Use esta tela para manter perguntas que avaliam requisitos legais, aplicabilidade, atendimento, evidencias e pendencias.</p><h2>Como operar</h2><ol><li>Escolha o questionario no seletor ao lado da paginacao.</li><li>Use <strong>+</strong> para incluir uma pergunta.</li><li>Clique em uma linha para habilitar editar ou excluir.</li><li>Use a busca para localizar perguntas.</li><li>Publique somente depois de revisar o conteudo e o tipo de resposta.</li></ol><p>O questionario Legal trata obrigacoes legais. Controles operacionais, treinamentos e monitoramentos do SGA devem ser tratados no questionario SGA.</p>',
 '<p>Use this screen to maintain questions that assess legal requirements, applicability, compliance, evidence and pending items.</p><h2>How to operate</h2><ol><li>Choose the questionnaire in the selector beside pagination.</li><li>Use <strong>+</strong> to add a question.</li><li>Click a row to enable edit or delete.</li><li>Use search to locate questions.</li><li>Publish only after reviewing the content and response type.</li></ol><p>The Legal questionnaire addresses legal obligations. SGA operational controls, training and monitoring belong in the SGA questionnaire.</p>',
 '<p>Use esta pantalla para mantener preguntas que evalúan requisitos legales, aplicabilidad, cumplimiento, evidencias y pendientes.</p><h2>Cómo operar</h2><ol><li>Elija el cuestionario en el selector junto a la paginación.</li><li>Use <strong>+</strong> para agregar una pregunta.</li><li>Haga clic en una fila para habilitar editar o eliminar.</li><li>Use la búsqueda para localizar preguntas.</li><li>Publique solo después de revisar el contenido y el tipo de respuesta.</li></ol><p>El cuestionario Legal trata obligaciones legales. Los controles operativos, capacitaciones y monitoreos del SGA pertenecen al cuestionario SGA.</p>',1),
('questionario_sga','Ajuda - Questionario SGA','Help - SGA Questionnaire','Ayuda - Cuestionario SGA',
 '<p>Use esta tela para avaliar o Sistema de Gestao Ambiental: licencas, aspectos ambientais, controles, treinamentos, infraestrutura, monitoramentos e indicadores.</p><h2>Como operar</h2><ol><li>Escolha o questionario no seletor ao lado da paginacao.</li><li>Inclua ou edite perguntas conforme o processo ambiental avaliado.</li><li>Defina o tipo de resposta, a ordem e se a pergunta e obrigatoria.</li><li>Revise as perguntas antes de publicar.</li></ol>',
 '<p>Use this screen to assess the Environmental Management System: licenses, environmental aspects, controls, training, infrastructure, monitoring and indicators.</p><h2>How to operate</h2><ol><li>Choose the questionnaire in the selector beside pagination.</li><li>Add or edit questions according to the environmental process assessed.</li><li>Set the response type, order and whether the question is required.</li><li>Review questions before publishing.</li></ol>',
 '<p>Use esta pantalla para evaluar el Sistema de Gestión Ambiental: licencias, aspectos ambientales, controles, capacitación, infraestructura, monitoreo e indicadores.</p><h2>Cómo operar</h2><ol><li>Elija el cuestionario en el selector junto a la paginación.</li><li>Agregue o edite preguntas según el proceso ambiental evaluado.</li><li>Defina el tipo de respuesta, el orden y si la pregunta es obligatoria.</li><li>Revise las preguntas antes de publicar.</li></ol>',1),
('questionario_quality','Ajuda - Questionario de Qualidade','Help - Quality Questionnaire','Ayuda - Cuestionario de Calidad',
 '<p>Use esta tela para estruturar auditorias de qualidade, nao conformidades, acoes corretivas e verificacao de eficacia.</p><h2>Como operar</h2><ol><li>Inclua perguntas objetivas e relacionadas ao processo de qualidade.</li><li>Escolha o tipo de resposta adequado.</li><li>Organize a ordem das perguntas e marque como obrigatoria quando necessario.</li><li>Revise e publique a versao homologada.</li></ol>',
 '<p>Use this screen to structure quality audits, nonconformities, corrective actions and effectiveness checks.</p><h2>How to operate</h2><ol><li>Add objective questions related to the quality process.</li><li>Choose the appropriate response type.</li><li>Organize question order and mark required when necessary.</li><li>Review and publish the approved version.</li></ol>',
 '<p>Use esta pantalla para estructurar auditorías de calidad, no conformidades, acciones correctivas y verificación de eficacia.</p><h2>Cómo operar</h2><ol><li>Agregue preguntas objetivas relacionadas con el proceso de calidad.</li><li>Elija el tipo de respuesta adecuado.</li><li>Organice el orden y marque como obligatoria cuando sea necesario.</li><li>Revise y publique la versión aprobada.</li></ol>',1),
('questionario_workflow','Ajuda - Questionario de Workflow','Help - Workflow Questionnaire','Ayuda - Cuestionario de Workflow',
 '<p>Use esta tela para manter checklists aplicados dentro de processos, aprovacoes e etapas de workflow.</p><h2>Como operar</h2><ol><li>Cadastre perguntas curtas e verificaveis.</li><li>Defina a ordem em que devem ser respondidas.</li><li>Use perguntas obrigatorias para pontos de controle essenciais.</li><li>Publique apos testar a execucao no processo.</li></ol>',
 '<p>Use this screen to maintain checklists applied inside processes, approvals and workflow steps.</p><h2>How to operate</h2><ol><li>Create short and verifiable questions.</li><li>Set the order in which they must be answered.</li><li>Use required questions for essential control points.</li><li>Publish after testing execution in the process.</li></ol>',
 '<p>Use esta pantalla para mantener listas de verificación aplicadas dentro de procesos, aprobaciones y etapas de workflow.</p><h2>Cómo operar</h2><ol><li>Registre preguntas cortas y verificables.</li><li>Defina el orden de respuesta.</li><li>Use preguntas obligatorias para puntos de control esenciales.</li><li>Publique después de probar la ejecución en el proceso.</li></ol>',1),
('questionario_supplier','Ajuda - Questionario de Fornecedores','Help - Supplier Questionnaire','Ayuda - Cuestionario de Proveedores',
 '<p>Use esta tela para perguntas de homologacao e avaliacao de fornecedores, incluindo risco, documentacao, capacidade e conformidade.</p><h2>Como operar</h2><ol><li>Inclua perguntas aplicaveis ao processo de homologacao.</li><li>Use peso e tipo de resposta de forma coerente com a avaliacao.</li><li>Revise a versao antes da publicacao.</li></ol>',
 '<p>Use this screen for supplier qualification and assessment questions, including risk, documentation, capacity and compliance.</p><h2>How to operate</h2><ol><li>Add questions applicable to supplier qualification.</li><li>Use weight and response type consistently with the assessment.</li><li>Review the version before publishing.</li></ol>',
 '<p>Use esta pantalla para preguntas de homologación y evaluación de proveedores, incluyendo riesgo, documentación, capacidad y conformidad.</p><h2>Cómo operar</h2><ol><li>Agregue preguntas aplicables a la homologación.</li><li>Use peso y tipo de respuesta de forma coherente con la evaluación.</li><li>Revise la versión antes de publicar.</li></ol>',1),
('questionario_esg','Ajuda - Questionario ESG','Help - ESG Questionnaire','Ayuda - Cuestionario ESG',
 '<p>Use esta tela para estruturar avaliacao de indicadores ambientais, sociais e de governanca.</p><h2>Como operar</h2><ol><li>Cadastre perguntas por indicador ou tema ESG.</li><li>Defina o tipo de resposta e a ordem.</li><li>Revise a consistencia dos indicadores antes de publicar.</li></ol>',
 '<p>Use this screen to structure assessment of environmental, social and governance indicators.</p><h2>How to operate</h2><ol><li>Create questions by ESG indicator or topic.</li><li>Set response type and order.</li><li>Review indicator consistency before publishing.</li></ol>',
 '<p>Use esta pantalla para estructurar la evaluación de indicadores ambientales, sociales y de gobernanza.</p><h2>Cómo operar</h2><ol><li>Registre preguntas por indicador o tema ESG.</li><li>Defina el tipo de respuesta y el orden.</li><li>Revise la consistencia de los indicadores antes de publicar.</li></ol>',1),
('questionario_projects','Ajuda - Questionario de Projetos','Help - Projects Questionnaire','Ayuda - Cuestionario de Proyectos',
 '<p>Use esta tela para checklists de fases, entregaveis, riscos e revisoes de projetos.</p><h2>Como operar</h2><ol><li>Cadastre perguntas associadas aos marcos do projeto.</li><li>Organize a ordem de verificacao.</li><li>Publique somente depois de validar o checklist com a equipe.</li></ol>',
 '<p>Use this screen for checklists of project phases, deliverables, risks and reviews.</p><h2>How to operate</h2><ol><li>Create questions associated with project milestones.</li><li>Organize the verification order.</li><li>Publish only after validating the checklist with the team.</li></ol>',
 '<p>Use esta pantalla para listas de verificación de fases, entregables, riesgos y revisiones de proyectos.</p><h2>Cómo operar</h2><ol><li>Registre preguntas asociadas a los hitos del proyecto.</li><li>Organice el orden de verificación.</li><li>Publique solo después de validar la lista con el equipo.</li></ol>',1),
('questionario_employee_integration','Ajuda - Integracao de Funcionarios','Help - Employee Integration Questionnaire','Ayuda - Cuestionario de Integración de Empleados',
 '<p>Use esta tela para perguntas de integracao, capacitacao inicial, ciencia de requisitos e responsabilidades de funcionarios.</p><h2>Como operar</h2><ol><li>Inclua perguntas adequadas ao processo de integracao.</li><li>Marque como obrigatorias as confirmacoes essenciais.</li><li>Revise e publique a versao validada.</li></ol>',
 '<p>Use this screen for onboarding, initial training, requirement acknowledgement and employee responsibility questions.</p><h2>How to operate</h2><ol><li>Add questions suitable for the onboarding process.</li><li>Mark essential confirmations as required.</li><li>Review and publish the validated version.</li></ol>',
 '<p>Use esta pantalla para preguntas de integración, capacitación inicial, conocimiento de requisitos y responsabilidades de empleados.</p><h2>Cómo operar</h2><ol><li>Agregue preguntas adecuadas al proceso de integración.</li><li>Marque como obligatorias las confirmaciones esenciales.</li><li>Revise y publique la versión validada.</li></ol>',1)
ON DUPLICATE KEY UPDATE transacao=VALUES(transacao),ativo=1;
